public String getWithMutex(String key) {
    String value = redis.get(key);
    if (value == null) {
        if (redis.setnx(key + ":lock", "1", Duration.ofSeconds(5))) {
            try {
                value = db.query(key);
                redis.setex(key, 3600 + new Random().nextInt(300), value); // Add jitter
            } finally {
                redis.del(key + ":lock");
            }
        } else {
            Thread.sleep(100);
            return getWithMutex(key); // Retry
        }
    }
    return value;
}
